// Делает небольшой выдуманный Statistic.csv в том же формате, что у Литнета (UTF-16 LE, табуляция).
import { writeFileSync } from 'node:fs';
const rows = [
  ['Статистика продаж'],
  ['Дата/месяц', 'Книга', 'Подписка/продажа', 'Цена', 'Кол-во', 'Гонорар', ''],
  ['02.09.2026', 'Книга А', 'Продажа', '100.00', '3', '210.00', ''],
  ['02.09.2026', 'Книга А', 'Продажа', '70.00', '1', '49.00', ''],
  ['02.09.2026', 'Книга Б', 'Подписка', '50.00', '2', '70.00', ''],
  ['01.09.2026', 'Книга А', 'Продажа', '100.00', '1', '70.00', ''],
  ['', '', '', 'Итого:7', '399,00 RUB', ''],
];
const text = rows.map((r) => r.join('\t')).join('\r\n') + '\r\n';
writeFileSync(new URL('./sample-statistic.csv', import.meta.url), Buffer.concat([Buffer.from([0xff, 0xfe]), Buffer.from(text, 'utf16le')]));
